using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Text.RegularExpressions;
namespace FortsStudio {
 public static partial class Exporter {
  static string N(double v){return v.ToString("0.############",CultureInfo.InvariantCulture);}public static string Q(string v){return "\""+(v??"").Replace("\\","\\\\").Replace("\"","\\\"").Replace("\r","").Replace("\n","\\n")+"\"";}
  static string Clone="local function fms_copy(t) if type(t) ~= 'table' then return t end local r = {} for k,v in pairs(t) do r[k] = fms_copy(v) end return r end\nlocal function fms_find(t, name) for _,v in ipairs(t) do if v.SaveName == name then return v end end error('FMS: missing base template ' .. name) end\n";
  static string AssetPath(string k,string suffix){return "assets/"+k+suffix;}
  static string OutputPath(string root,string file){string parent=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string result=Path.GetFullPath(Path.Combine(parent,file.Replace('/',Path.DirectorySeparatorChar)));if(!result.StartsWith(parent,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Небезопасный путь ресурса мода.");return result;}
  static void Write(string root,string file,string body){string f=OutputPath(root,file);Directory.CreateDirectory(Path.GetDirectoryName(f));File.WriteAllText(f,body,Encoding.Unicode);}
  static void Bytes(string root,string file,byte[] data){string f=OutputPath(root,file);Directory.CreateDirectory(Path.GetDirectoryName(f));File.WriteAllBytes(f,data);}
  static string Sprite(string name,string texture){string f="{ Frames = { { texture = path .. "+Q("/"+texture)+" }, mipmap = true } }";return "table.insert(Sprites, { Name = "+Q(name)+", States = { Normal = "+f+", Idle = "+f+", Fire = "+f+", Reload = "+f+", ReloadEnd = "+f+", Rollover = "+f+", Pressed = "+f+", Disabled = "+f+" } })\n";}
  static string HudSprite(string name,string key){var s=new StringBuilder("table.insert(Sprites, { Name = "+Q(name)+", States = { ");string[] states={"Normal","Rollover","Pressed","Disabled"};for(int i=0;i<states.Length;i++)s.Append(states[i]+" = { Frames = { { texture = path .. "+Q("/"+AssetPath(key,"-hud-"+i+".tga"))+", bottom = 0.664, right = 1 } } }, ");return s.Append("} })\n").ToString();}
  public static List<string> Validate(Project p){var errors=new List<string>();if(!Regex.IsMatch(p.Folder??"",@"^[a-z][a-z0-9_\-]{2,55}$"))errors.Add("Имя папки: 3–56 латинских букв, цифр, _ или -. Начните с буквы.");try{GameInstallation.RequireRoot(p.GameRoot);}catch(InvalidOperationException ex){errors.Add(ex.Message);}if(p.Entities.Count==0)errors.Add("Добавьте хотя бы один объект.");var keys=new HashSet<string>();foreach(var e in p.Entities){if(e.Kind=="materials"&&(Double.IsNaN(e.Thickness)||Double.IsInfinity(e.Thickness)||e.Thickness<1||e.Thickness>256))errors.Add(e.Key+": толщина изображения должна быть 1–256 игровых единиц.");if(!Regex.IsMatch(e.Key??"",@"^[a-z][a-z0-9_]{1,63}$"))errors.Add("Неверный SaveName: "+e.Key);if(!keys.Add(e.Key))errors.Add("Повторяется SaveName: "+e.Key);if(Catalog.Templates.Any(t=>t.Key==e.Key))errors.Add("SaveName совпадает со штатным объектом: "+e.Key);if(e.Kind=="weapons"&&e.Ammo.Count==0)errors.Add(e.NameRu+": выберите снаряд.");foreach(string a in e.Ammo)if(!p.Entities.Any(x=>x.Kind=="projectiles"&&x.Key==a)&&!Catalog.Templates.Any(x=>x.Kind=="projectiles"&&x.Key==a))errors.Add(e.NameRu+": не найден снаряд "+a);foreach(var param in Catalog.Parameters(e.Kind)){double v=e.V(param.Key,param.Default);if(Double.IsNaN(v)||Double.IsInfinity(v)||v<param.Min)errors.Add(e.Key+": недопустимое значение "+param.Key);}if(e.Kind=="weapons"&&e.V("MinFireSpeed",0)>e.V("MaxFireSpeed",0))errors.Add(e.Key+": минимальная скорость больше максимальной.");foreach(var ex in e.Extras){if(!Regex.IsMatch(ex.Key??"",@"^[A-Za-z_][A-Za-z0-9_]*$"))errors.Add(e.Key+": неверное имя дополнительного поля "+ex.Key);}}
   foreach(var c in p.Chains.Where(c=>c.Enabled)){if(c.Event=="native_impact"&&(!p.Entities.Any(x=>x.Kind=="projectiles"&&x.Key==c.Source)))errors.Add(c.Name+": для осколков выберите снаряд проекта.");if(c.Event=="native_impact"&&c.Blocks.Any(b=>b.Kind=="condition"&&b.Type!="material"))errors.Add(c.Name+": событие осколков поддерживает фильтр материала; для команд используйте обычное попадание.");if(c.Event!="native_impact"&&c.Blocks.Any(b=>b.Type=="fragments"))errors.Add(c.Name+": осколки используйте с событием «Удар снаряда: осколки».");}
   ValidateExtensions(p,errors);TechnologyRules.Validate(p,errors);ValidateClusters(p,errors);ValidateHybrid(p,errors);ValidateArtwork(p,errors);return errors;
  }
  public static bool NeedsDlc(Project p){return p.Chains.Where(c=>c.Enabled).SelectMany(c=>AllBlocks(c.Blocks)).Any(b=>b.Type=="convert_projectile"||b.Type=="spawn_projectile")||p.Entities.Any(e=>e.HybridAA||e.Kind=="weapons"&&(e.Ammo.Count>1||p.Entities.Any(pr=>e.Ammo.Contains(pr.Key)&&pr.FiniteAmmo)));}
  static string TemplateDofile(Template t){if(!t.Script.StartsWith("mods/"))return "dofile("+Q(t.Script)+")\n";string[] parts=t.Script.Split('/');string original="mods/"+parts[1];return "local fms_template_path = path\npath = "+Q(original)+"\ndofile("+Q(t.Script)+")\npath = fms_template_path\n";}
  static string ExtraValue(string s){double n;bool b;if(Double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out n))return N(n);if(Boolean.TryParse(s,out b))return b?"true":"false";return Q(s);}
  static string Overrides(Entity e,string target,string scope){var b=new StringBuilder();foreach(var par in Catalog.Parameters(e.Kind)){if(par.Scope=="meta"||((scope=="list")!=(par.Scope=="list")))continue;if(e.Kind=="materials"||e.Kind=="projectiles"||scope!="list")b.Append(target+par.Key+" = "+N(e.V(par.Key,par.Default))+"\n");else b.Append(target+par.Key+" = "+N(e.V(par.Key,par.Default))+"\n");}foreach(var ex in e.Extras.Where(x=>x.Scope==scope))b.Append(target+ex.Key+" = "+ExtraValue(ex.Value)+"\n");return b.ToString();}
  public static string Build(Project p,string parent){var errors=Validate(p);if(errors.Count>0)throw new Exception(String.Join("\n",errors));Assets.Resolve(p.GameRoot);string root=Path.GetFullPath(Path.Combine(parent,p.Folder));if(Directory.Exists(root))throw new Exception("Папка сборки уже существует: "+root);Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,".fms-owned"),p.Id);
   var includes=new List<string>();if(p.Entities.Any(e=>e.HybridAA||Catalog.Get(e).ListSource.Contains("weapon_pack")))includes.Add("weapon_pack");if(NeedsDlc(p))includes.Add("dlc2");
   Write(root,"mod.lua","Selectable = true\nCategory = "+Q(p.Entities.Any(e=>e.Kind=="weapons")?"Weapons":"Materials")+"\nPriority = "+(includes.Count>0?"9":"5")+"\n"+(NeedsDlc(p)?"RequiresHighSeas = true\n":"")+(includes.Count>0?"Include = { "+String.Join(", ",includes.Select(Q))+" }\n":""));
   Write(root,"displayname.lua","DisplayName = { English = L"+Q(p.NameEn)+", Russian = L"+Q(p.NameRu)+" }\n");
   var lists=new Dictionary<string,StringBuilder>();foreach(string kind in new[]{"materials","devices","weapons","projectiles"})lists[kind]=new StringBuilder(Clone+"Sprites = Sprites or {}\n");
   foreach(var e in p.Entities){string tab=Catalog.Table(e.Kind);var t=Catalog.Get(e);var l=lists[e.Kind];string ico="fms_"+p.Id.Substring(0,8)+"_"+e.Key+"_icon",detail=ico+"_detail",body=AssetPath(e.Key,"-body.tga"),icon=AssetPath(e.Key,"-icon.tga");using(var im=Assets.Icon(e,p.GameRoot))Bytes(root,icon,Assets.Tga(im,0));for(int state=0;state<4;state++)using(var card=Assets.HudCard(e,p.GameRoot,state))Bytes(root,AssetPath(e.Key,"-hud-"+state+".tga"),Assets.Tga(card,0));l.Append(HudSprite(ico,e.Key));l.Append(Sprite(detail,icon));
    l.Append("do\nlocal item = fms_copy(fms_find("+tab+", "+Q(t.Key)+"))\nitem.SaveName = "+Q(e.Key)+"\n");if(e.Kind!="projectiles")l.Append("item.Icon = "+Q(ico)+"\nitem.Enabled = true\nitem.ShowInEditor = true\nitem.ShowOnHUD = true\nitem.Upgrades = nil\nitem.Prerequisite = nil\nitem.PrerequisiteAlt = nil\n");
    if(e.Kind=="devices")l.Append("item.Tech = "+(e.IsTechnology?"true":"false")+"\n");
    if(e.IsTechnology)l.Append("item.Detail = "+Q(detail)+"\nitem.ObserverBuildEvent = true\nitem.SelectEffect = 'ui/hud/technology/ui_technology'\n");
    if(e.Kind=="weapons"&&e.Art!=null&&e.Art.Enabled)l.Append("item.Detail = "+Q(detail)+"\n");
    if(e.Kind=="materials"){
     l.Append("item.Detail = "+Q(detail)+"\n");
     l.Append(Overrides(e,"item.","script"));foreach(var flag in e.Flags)l.Append("item."+flag.Key+" = "+(flag.Value?"true":"false")+"\n");
     var frames=MaterialVisuals.Frames(e,p.GameRoot);string spr="fms_"+e.Key+"_beam";var beam=new StringBuilder();
     for(int frame=0;frame<frames.Length;frame++){var img=MaterialVisuals.Beam(e,p.GameRoot,frame);if(img==null)throw new Exception("Не прочитана текстура балки "+e.Key);string tex=AssetPath(e.Key,"-beam-"+frame+".tga");Bytes(root,tex,Assets.Tga(img,0));double duration=frames.Length==4?(frame==0?(e.Template=="armour"?.05:e.Template=="backbracing"?.1:.01):frame==3?(e.Template=="armour"?.351:e.Template=="backbracing"?.301:.331):(e.Template=="bracing"?.33:.3)):1.0/frames.Length;beam.Append("{ texture = path .. "+Q("/"+tex)+", duration = "+N(duration)+" }, ");}
     l.Append("table.insert(Sprites, { Name = "+Q(spr)+", States = { Normal = { Frames = { "+beam+"repeatS = true, mipmap = true } } } })\nitem.Sprite = "+Q(spr)+"\n");

    } else if(e.Kind=="projectiles"){
     l.Append(Overrides(e,"item.","script"));foreach(var flag in e.Flags)l.Append("item."+flag.Key+" = "+(flag.Value?"true":"false")+"\n");if(e.Texture.Length>0){var img=Assets.Body(e,p.GameRoot);if(img==null)throw new Exception("Не прочитана текстура "+e.Key);Bytes(root,body,Assets.Tga(img,0));l.Append("item.Projectile = nil\nitem.ProjectileSprite = path .. "+Q("/"+body)+"\n");}
     foreach(var chain in p.Chains.Where(c=>c.Enabled&&c.Event=="native_impact"&&c.Source==e.Key)){
      string material=chain.Blocks.Where(b=>b.Kind=="condition"&&b.Type=="material").Select(b=>b.Value).FirstOrDefault()??"default";var fragment=chain.Blocks.FirstOrDefault(b=>b.Kind=="action"&&b.Type=="fragments");var effect=chain.Blocks.FirstOrDefault(b=>b.Kind=="action"&&b.Type=="effect");l.Append("item.Effects = item.Effects or {}\nitem.Effects.Impact = item.Effects.Impact or {}\nitem.Effects.Impact["+Q(material)+"] = { Effect = "+Q(effect!=null&&effect.Value.Length>0?effect.Value:"effects/impact_heavy.lua")+", Splash = true, Terminate = true, PosT = 1, Offset = 1");if(fragment!=null){double spread=.12;Double.TryParse(fragment.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out spread);l.Append(", Projectile = { Count = "+N(Math.Max(1,fragment.Number))+", Type = "+Q(fragment.Value.Length>0?fragment.Value:"machinegun")+", StdDev = "+N(spread)+" }");}l.Append(" }\n");
     }
     l.Append(ProjectileResources(p,root,e));
     if(e.Texture.Length>0){var image=Assets.Body(e,p.GameRoot);int width=Math.Max(2,(int)Math.Round(e.ProjectileImageWidth*2));int height=Math.Max(2,(int)Math.Round(width*(double)image.Height/image.Width));using(var fitted=Raster.Resize(image,width,height))Bytes(root,body,Assets.Tga(fitted,0));l.Append("item.Projectile = { Root = { Name = 'Root', Angle = 0, Sprite = path .. "+Q("/"+body)+", Scale = "+N(e.ProjectileVisualScale)+" } }\n");}
     else if(Math.Abs(e.ProjectileVisualScale-1)>.0001)l.Append("if item.Projectile and item.Projectile.Root then item.Projectile.Root.Scale = (item.Projectile.Root.Scale or 1) * "+N(e.ProjectileVisualScale)+" end\n");
     l.Append(ClusterProjectileDefinition(e));
    } else {
     string file=(e.Kind=="weapons"?"weapons/":"devices/")+e.Key+".lua";l.Append("item.FileName = path .. "+Q("/"+file)+"\n"+Overrides(e,"item.","list"));
     var script=new StringBuilder(TemplateDofile(t)+Overrides(e,"","script"));script.Append("SelectionOffset = { "+N(e.V("SelectionOffsetX",0))+", "+N(e.V("SelectionOffsetY",-40))+" }\n");foreach(var flag in e.Flags)script.Append(flag.Key+" = "+(flag.Value?"true":"false")+"\n");
     string prefix="fms_"+e.Key+"_";script.Append("local fms_names = {}\nfor _, s in ipairs(Sprites or {}) do local old = s.Name s.Name = "+Q(prefix)+" .. old fms_names[old] = s.Name end\nlocal function fms_remap(n) if not n then return end if fms_names[n.Sprite] then n.Sprite = fms_names[n.Sprite] end for _,c in ipairs(n.ChildrenInFront or {}) do fms_remap(c) end for _,c in ipairs(n.ChildrenBehind or {}) do fms_remap(c) end end\nfms_remap(Root)\n");
     if(e.Texture.Length>0){var img=Assets.Body(e,p.GameRoot);if(img==null)throw new Exception("Не прочитана текстура "+e.Key);Bytes(root,body,Assets.Tga(img,0));script.Append("for _,s in ipairs(Sprites) do if s.Name == "+Q(prefix+t.Sprite)+" then s.States.Normal = { Frames = { { texture = path .. "+Q("/"+body)+" }, mipmap = true } } s.States.Idle = s.States.Normal end end\n");}
     script.Append(ScriptResources(p,root,e));
     if(e.Kind=="weapons")script.Append(WeaponArtworkScript(p,root,e));
     if(e.Kind=="weapons"){
      script.Append("Projectile = "+Q(e.Ammo[0])+"\n");if(!e.HybridAA&&(e.Ammo.Count>1||p.Entities.Any(x=>e.Ammo.Contains(x.Key)&&x.FiniteAmmo))){
       script.Append("dlc2_Ammunition = {}\n");foreach(string ammo in e.Ammo){var pr=p.Entities.FirstOrDefault(x=>x.Kind=="projectiles"&&x.Key==ammo);string mode="fms_"+e.Key+"_"+ammo+"_mode";script.Append(Sprite(mode,AssetPath(pr==null?e.Key:pr.Key,"-icon.tga")));script.Append("table.insert(dlc2_Ammunition, { Sprite = "+Q(mode)+", StringId = "+Q("Weapon.fms_ammo_"+ammo)+", Projectile = "+Q(ammo));if(pr!=null&&pr.FiniteAmmo)script.Append(", Devices = { { Name = "+Q("fms_ammo_"+ammo)+", Consume = true } }");script.Append(" })\n");}
      }
     }
     if(e.Kind=="weapons")script.Append(HybridWeaponScript(e));
     Write(root,file,script.ToString());
    }
    if(e.Kind=="materials")l.Append(MaterialResources(p,root,e));
    if(e.Kind!="projectiles"&&e.RequireTechnology)l.Append("item.Prerequisite = "+Q(e.RequiredTechnology)+"\nitem.PrerequisiteAlt = nil\n");
    l.Append("table.insert("+tab+", item)\nend\n");
   }
   foreach(var kind in lists.Keys)if(p.Entities.Any(e=>e.Kind==kind))Write(root,Catalog.ListPath(kind),lists[kind].ToString());
   var finite=p.Entities.Where(e=>e.Kind=="projectiles"&&e.FiniteAmmo&&p.Entities.Any(w=>w.Kind=="weapons"&&w.Ammo.Contains(e.Key))).ToList();if(finite.Count>0){var list=new StringBuilder("Sprites = Sprites or {}\n");foreach(var e in finite){string aid="fms_ammo_"+e.Key,ico=aid+"_icon";list.Append(HudSprite(ico,e.Key));list.Append("table.insert(Devices, { SaveName = "+Q(aid)+", FileName = path .. "+Q("/devices/"+aid+".lua")+", Icon = "+Q(ico)+", Detail = 'hud-detail-battery', Enabled = true, ShowInEditor = true, BuildTimeComplete = "+N(e.AmmoBuildTime)+", ScrapPeriod = 1, MetalCost = "+N(e.AmmoMetal)+", EnergyCost = "+N(e.AmmoEnergy)+", MetalRepairCost = 0, EnergyRepairCost = 0, MaxUpAngle = 20, BuildOnGroundOnly = false, SelectEffect = 'ui/hud/devices/ui_devices' })\n");Write(root,"devices/"+aid+".lua","dofile('devices/battery.lua')\nMass = 5\nHitPoints = 50\nScale = 0.55\nEnergyStorageCapacity = 0\nDeviceSplashDamage = 0\nStructureSplashDamage = 0\nConsumeEffect = 'mods/dlc2/effects/ammo_consumption.lua'\n");}Write(root,"devices/ammo_list.lua",list.ToString());}
   foreach(string lang in new[]{"russian","english"}){bool ru=lang=="russian";foreach(string kind in new[]{"materials","devices","weapons"}){var sb=new StringBuilder();string table=kind=="materials"?"Material":kind=="devices"?"Device":"Weapon";foreach(var e in p.Entities.Where(e=>e.Kind==kind)){sb.Append(table+"["+Q(e.Key)+"] = L"+Q(ru?e.NameRu:e.NameEn)+"\n"+table+"["+Q(e.Key+"Tip2")+"] = L"+Q(ru?e.DescriptionRu:e.DescriptionEn)+"\n");}if(kind=="weapons")foreach(var e in p.Entities.Where(e=>e.Kind=="projectiles"))sb.Append("Weapon["+Q("fms_ammo_"+e.Key)+"] = L"+Q(ru?e.NameRu:e.NameEn)+"\n");if(kind=="devices")foreach(var e in finite)sb.Append("Device["+Q("fms_ammo_"+e.Key)+"] = L"+Q((ru?e.NameRu:e.NameEn)+(ru?" · боеприпас":" ammunition"))+"\n");if(sb.Length>0)Write(root,"mods/language-"+lang+"/"+kind+"/strings.lua",sb.ToString());}}
   ExportAudioResources(p,root);
   ExportHybridAi(p,root);
   Write(root,"script.lua",Runtime(p)+ClusterRuntime(p)+HybridRuntime(p));
   using(var im=new System.Drawing.Bitmap(1024,576))using(var g=System.Drawing.Graphics.FromImage(im)){g.Clear(System.Drawing.Color.FromArgb(18,27,35));g.DrawString("FORTS / MOD STUDIO",new System.Drawing.Font("Segoe UI",34,System.Drawing.FontStyle.Bold),System.Drawing.Brushes.White,60,70);g.DrawString(p.NameRu,new System.Drawing.Font("Segoe UI",26),System.Drawing.Brushes.LightGreen,new System.Drawing.RectangleF(60,175,900,200));g.DrawString(p.Entities.Count+" объектов   •   "+p.Chains.Count+" сценариев",new System.Drawing.Font("Segoe UI",18),System.Drawing.Brushes.LightGray,60,420);im.Save(Path.Combine(root,"preview.jpg"),System.Drawing.Imaging.ImageFormat.Jpeg);}
   if(!String.IsNullOrEmpty(p.CoverImage)){var cover=Assets.Image(p.CoverImage,p.GameRoot);if(cover==null)throw new Exception("Не удалось прочитать обложку мода.");using(var image=Raster.Fit(cover,1024,576))image.Save(Path.Combine(root,"preview.jpg"),System.Drawing.Imaging.ImageFormat.Jpeg);}
   Storage.Save(p,Path.Combine(root,"project.fms.json"));File.WriteAllText(Path.Combine(root,"INSTALL.txt"),"Forts Mod Studio\r\n\r\nExtract this entire folder into Forts/data/mods/.\r\nSandbox > choose map > Mods > Player. Search the project name.\r\nKeep all filters unchecked while searching. Restart Forts after installation.\r\n",Encoding.UTF8);
   return root;
  }
  public static List<string> Parse(string root,string game){
   var errors=new List<string>();string trusted=GameInstallation.RequireRoot(game),compiler=Path.Combine(trusted,"LuaPlusC.exe");
   if(!File.Exists(compiler)){errors.Add("Не найден игровой анализатор LuaPlusC.exe");return errors;}
   foreach(string file in Directory.GetFiles(Path.GetFullPath(root),"*.lua",SearchOption.AllDirectories)){
    var info=new ProcessStartInfo(compiler,"-p \""+file+"\""){WorkingDirectory=trusted,UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};
    using(var proc=Process.Start(info)){
     var stderr=System.Threading.Tasks.Task.Factory.StartNew(()=>proc.StandardError.ReadToEnd());
     var stdout=System.Threading.Tasks.Task.Factory.StartNew(()=>proc.StandardOutput.ReadToEnd());
     if(!proc.WaitForExit(30000)){try{proc.Kill();}catch(InvalidOperationException){}errors.Add(Path.GetFileName(file)+": "+"Проверка Lua превысила 30 секунд.");break;}
     if(!System.Threading.Tasks.Task.WaitAll(new System.Threading.Tasks.Task[]{stderr,stdout},5000)){errors.Add(Path.GetFileName(file)+": "+"Анализатор Lua не завершил вывод журнала.");break;}
     if(proc.ExitCode!=0)errors.Add(Path.GetFileName(file)+": "+stderr.Result+stdout.Result);
    }
   }return errors;
  }
  public static string Install(Project p){string mods=Path.GetFullPath(Path.Combine(p.GameRoot,"data","mods"));string state=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FortsModStudio2","builds",Guid.NewGuid().ToString("N"));string built=Build(p,state);var errors=Parse(built,p.GameRoot);if(errors.Count>0)throw new Exception(String.Join("\n",errors));string dest=Path.GetFullPath(Path.Combine(mods,p.Folder));if(!dest.StartsWith(mods+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Небезопасный путь установки.");if(Directory.Exists(dest)){string marker=Path.Combine(dest,".fms-owned");if(!File.Exists(marker)||File.ReadAllText(marker)!=p.Id)throw new Exception("Папка "+dest+" принадлежит другому моду. Измените имя папки проекта.");string backup=Path.Combine(mods,".fms-history",p.Folder+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));Directory.CreateDirectory(Path.GetDirectoryName(backup));Directory.Move(dest,backup);}CopyTree(built,dest);p.LastInstall=dest;return dest;}
  public static void CopyTree(string source,string dest){Directory.CreateDirectory(dest);foreach(string file in Directory.GetFiles(source))File.Copy(file,Path.Combine(dest,Path.GetFileName(file)),true);foreach(string dir in Directory.GetDirectories(source))CopyTree(dir,Path.Combine(dest,Path.GetFileName(dir)));}
  public static string Zip(Project p,string file){string tmp=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FortsModStudio2","builds",Guid.NewGuid().ToString("N"));string built=Build(p,tmp);var errors=Parse(built,p.GameRoot);if(errors.Count>0)throw new Exception(String.Join("\n",errors));if(File.Exists(file))File.Delete(file);ZipFile.CreateFromDirectory(built,file,CompressionLevel.Optimal,true);return file;}
  public static string LogReport(Project p){string users=Path.Combine(p.GameRoot,"users");if(!Directory.Exists(users))return "Папка журналов не найдена.";string file=Directory.GetFiles(users,"log.txt",SearchOption.AllDirectories).OrderByDescending(File.GetLastWriteTime).FirstOrDefault();if(file==null)return "Журнал пока не создан.";var lines=File.ReadAllLines(file);var own=lines.Where(s=>s.IndexOf(p.Folder,StringComparison.OrdinalIgnoreCase)>=0||s.Contains("FMS_LOADED")).ToArray();var failures=lines.Where(s=>s.StartsWith("Error")||s.Contains("script not found")||s.Contains("FMS:")).ToArray();return "Журнал: "+file+"\r\n\r\n"+(own.Length>0?String.Join("\r\n",own):"Этот проект пока не отмечен в текущем журнале. Перезапустите Forts и активируйте мод во вкладке «Игрок».")+"\r\n\r\nПоследние ошибки игры (могут относиться к другим модам):\r\n"+String.Join("\r\n",failures.Reverse().Take(18).Reverse());}
 }
